/* Review-oriented structural 3D model viewer. Geometry is generated by the backend from takeoff records. */
window.renderStructural3D = async function (main, api, P, esc, icon) {
  const model = await api(P("/3d-model"));
  const typeNames = { footing: "Footings", raft: "Rafts", blinding: "Blinding", pedestal: "Pedestals", column: "Columns", wall: "Walls", beam: "Beams", slab: "Slabs" };
  const colors = { footing: "#80cbc4", raft: "#26a69a", blinding: "#d4a84f", pedestal: "#ba68c8", column: "#ef6c6c", wall: "#b58b72", beam: "#ffb74d", slab: "#64b5f6" };
  const colorClass = s => s === "inferred" ? "b-warning" : "b-success";
  const statusText = s => s === "inferred" ? "Inferred" : "Measured";
  const dimsText = d => Object.entries(d || {}).filter(([, v]) => v && v.value != null)
    .map(([k, v]) => `${k.replace(/_/g, " ")}: ${Number(v.value).toFixed(3)} ${v.unit || ""}`.trim());

  main.innerHTML = `<div class="banner warn model3d-disclaimer">${icon("info")}<div><b>Generated structural model.</b> Built from 2D takeoff outlines and available dimensions/levels. Review inferred placements; this is not a native or verified coordination model.</div></div>
    <div class="model3d-summary"><div><b>${model.summary.modelled}</b><span>modelled</span></div><div><b>${model.summary.inferred}</b><span>inferred placement</span></div><div><b>${model.summary.not_modelled}</b><span>not modelled</span></div></div>
    <div class="model3d-layout"><aside class="model3d-panel"><h3>Model controls</h3><label for="m3Floor">Floor</label><select id="m3Floor"><option value="">All floors</option>${model.floors.map(f => `<option value="${esc(f)}">${esc(f)}</option>`).join("")}</select>
      <label for="m3Type">Element type</label><select id="m3Type"><option value="">All types</option>${model.types.map(t => `<option value="${esc(t)}">${esc(typeNames[t] || t)}</option>`).join("")}</select>
      <label for="m3Search">Find element</label><input id="m3Search" placeholder="Mark or description">
      <div class="model3d-list-head"><h3>Elements</h3><span id="m3Count"></span></div><div id="m3List" class="model3d-list"></div>
      ${model.not_modelled.length ? `<details class="model3d-missing"><summary>Not modelled (${model.not_modelled.length})</summary><div>${model.not_modelled.map(e => `<div class="model3d-missing-item"><b>${esc(e.uid)}</b><div>${esc(e.reason)}</div></div>`).join("")}</div></details>` : ""}${model.not_modelled.some(e => e.reason.includes("reprocess")) ? `<a class="btn sec small model3d-reprocess" href="#/processing">Reprocess to include slab openings</a>` : ""}</aside>
      <section class="model3d-stage"><canvas id="model3dCanvas" aria-label="Orbitable 3D structural model"></canvas>
        <div class="model3d-toolbar"><button id="m3Fit" title="Fit model">${icon("fit")}Fit</button><button id="m3ZoomOut" title="Zoom out" aria-label="Zoom out">− <span>Zoom out</span></button><button id="m3ZoomIn" title="Zoom in" aria-label="Zoom in">+ <span>Zoom in</span></button><button id="m3Top">Top</button><button id="m3Iso">Isometric</button></div>
        <div class="model3d-help">Drag to orbit · right-drag or Shift-drag to pan · scroll to zoom</div><div class="model3d-axis">X/Y plan · Z elevation</div><div id="m3Fallback" class="model3d-fallback hidden"></div></section>
      <aside id="m3Info" class="model3d-panel"><h3>Element details</h3><p class="small">Select an element from the list to inspect its dimensions, placement, and drawing evidence.</p></aside>
    </div>`;

  const canvas = main.querySelector("#model3dCanvas");
  const gl = canvas.getContext("webgl", { antialias: true, alpha: false });
  if (!gl) {
    main.querySelector("#m3Fallback").classList.remove("hidden");
    main.querySelector("#m3Fallback").textContent = "3D graphics are unavailable in this browser. Enable WebGL or use a supported desktop browser.";
    canvas.classList.add("hidden");
  }

  const meshes = model.meshes || [];
  let selected = null;
  let visible = [];
  let buffers = [];
  const floorFilter = main.querySelector("#m3Floor"), typeFilter = main.querySelector("#m3Type"), search = main.querySelector("#m3Search");
  const list = main.querySelector("#m3List"), count = main.querySelector("#m3Count"), info = main.querySelector("#m3Info");

  function selectMesh(mesh) {
    selected = mesh;
    const sourceId = mesh.sources?.find(s => s.drawing_id)?.drawing_id || mesh.drawing_id;
    info.innerHTML = `<h3>Element details</h3><div class="model3d-detail-title">${esc(mesh.description || mesh.uid)}</div><div class="model3d-badges"><span class="badge ${colorClass(mesh.model_status)}">${statusText(mesh.model_status)}</span><span class="badge b-outline">${esc((typeNames[mesh.element_type] || mesh.element_type).replace(/s$/, ""))}</span><span class="badge b-outline">${esc(mesh.floor || "—")}</span></div>
      <div class="model3d-kv">${dimsText(mesh.dimensions).map(x => `<div>${esc(x)}</div>`).join("") || `<div class="small">No dimensions recorded.</div>`}
        ${mesh.quantity != null ? `<div><b>Takeoff quantity</b><br>${Number(mesh.quantity).toFixed(3)} ${esc(mesh.unit || "")}</div>` : ""}
        <div class="model3d-placement"><b>3D placement</b><br>${esc(mesh.placement_note || "Placement unavailable")}</div>
        <div><b>Source drawing</b><br>${esc(mesh.drawing || "—")} · ${esc(mesh.layer || "—")}${sourceId ? ` <a href="#/viewer/${encodeURIComponent(sourceId)}">Open 2D drawing</a>` : ""}</div>
        <div><b>Dimension source</b><br>${esc(mesh.dimension_source || "—")}${mesh.dimension_assumed ? " · assumed" : ""}${mesh.confidence != null ? ` · confidence ${Math.round(mesh.confidence * 100)}%` : ""}</div>
        ${mesh.sources?.length ? `<div><b>Evidence</b>${mesh.sources.map(s => `<div class="small">${esc(s.note || s.drawing || "Source record")}</div>`).join("")}</div>` : ""}
        ${mesh.flags?.length ? `<div><b>Review flags</b>${mesh.flags.map(f => `<div class="small">${esc(f.title || f.message || f.code || f)}</div>`).join("")}</div>` : ""}</div>`;
    renderList();
    if (gl) draw();
  }

  function renderList() {
    const q = search.value.trim().toLowerCase();
    visible = meshes.filter(m => (!floorFilter.value || m.floor === floorFilter.value) && (!typeFilter.value || m.element_type === typeFilter.value)
      && (!q || `${m.uid} ${m.mark || ""} ${m.description || ""}`.toLowerCase().includes(q)));
    count.textContent = `${visible.length}`;
    list.innerHTML = visible.map((m, i) => `<button type="button" class="model3d-row${selected?.uid === m.uid ? " selected" : ""}" data-m3-index="${i}">
      <i style="background:${colors[m.element_type] || "#b0bec5"}"></i><span><b>${esc(m.mark || m.uid)}</b><small>${esc(m.description || "")}</small></span><em class="${m.model_status === "inferred" ? "inferred" : ""}">${statusText(m.model_status)}</em></button>`).join("") || `<div class="small model3d-empty-list">No elements match these filters.</div>`;
    list.querySelectorAll("[data-m3-index]").forEach(b => b.onclick = () => selectMesh(visible[Number(b.dataset.m3Index)]));
  }
  floorFilter.onchange = renderList;
  typeFilter.onchange = renderList;
  search.oninput = renderList;
  renderList();

  if (!gl || !meshes.length) {
    if (!meshes.length) {
      const fallback = main.querySelector("#m3Fallback");
      fallback.classList.remove("hidden");
      fallback.textContent = model.not_modelled.length ? "No solids could be generated from the current takeoff. Review the Not modelled list for missing dimensions or outlines." : "No structural elements are available in this processing run.";
      canvas.classList.add("hidden");
    }
    return;
  }

  const vertexShader = `attribute vec3 aPos; attribute vec3 aNormal; uniform mat4 uMvp; varying float vLight; void main(){gl_Position=uMvp*vec4(aPos,1.0);vLight=max(dot(normalize(aNormal),normalize(vec3(-0.35,-0.45,0.82))),0.22);}`;
  const fragmentShader = `precision mediump float; uniform vec3 uColor; varying float vLight; void main(){gl_FragColor=vec4(uColor*vLight,1.0);}`;
  function shader(type, source) { const s = gl.createShader(type); gl.shaderSource(s, source); gl.compileShader(s); if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s)); return s; }
  let program;
  try {
    program = gl.createProgram();
    gl.attachShader(program, shader(gl.VERTEX_SHADER, vertexShader));
    gl.attachShader(program, shader(gl.FRAGMENT_SHADER, fragmentShader));
    gl.linkProgram(program);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
  } catch (e) {
    const fallback = main.querySelector("#m3Fallback"); fallback.classList.remove("hidden"); fallback.textContent = `Could not start 3D graphics: ${e.message}`; canvas.classList.add("hidden"); return;
  }
  gl.useProgram(program);
  const aPos = gl.getAttribLocation(program, "aPos"), aNormal = gl.getAttribLocation(program, "aNormal");
  const uMvp = gl.getUniformLocation(program, "uMvp"), uColor = gl.getUniformLocation(program, "uColor");
  gl.enable(gl.DEPTH_TEST); gl.disable(gl.CULL_FACE); gl.clearColor(0.055, 0.075, 0.09, 1);

  function meshBuffer(mesh) {
    const src = mesh.vertices || [], packed = [];
    for (let i = 0; i + 8 < src.length; i += 9) {
      const ax = src[i], ay = src[i + 1], az = src[i + 2], bx = src[i + 3], by = src[i + 4], bz = src[i + 5], cx = src[i + 6], cy = src[i + 7], cz = src[i + 8];
      const ux = bx - ax, uy = by - ay, uz = bz - az, vx = cx - ax, vy = cy - ay, vz = cz - az;
      let nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
      const nl = Math.hypot(nx, ny, nz) || 1; nx /= nl; ny /= nl; nz /= nl;
      for (let j = 0; j < 9; j += 3) packed.push(src[i + j], src[i + j + 1], src[i + j + 2], nx, ny, nz);
    }
    const buffer = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER, buffer); gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(packed), gl.STATIC_DRAW);
    return { buffer, count: packed.length / 6, mesh };
  }
  buffers = meshes.map(meshBuffer);

  const norm = v => { const l = Math.hypot(...v) || 1; return v.map(x => x / l); };
  const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
  const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
  function lookAt(eye, center, up) {
    const z = norm(eye.map((v, i) => v - center[i])), x = norm(cross(up, z)), y = cross(z, x);
    return new Float32Array([x[0], y[0], z[0], 0, x[1], y[1], z[1], 0, x[2], y[2], z[2], 0,
      -dot(x, eye), -dot(y, eye), -dot(z, eye), 1]);
  }
  function perspective(fov, aspect, near, far) {
    const f = 1 / Math.tan(fov / 2), nf = 1 / (near - far);
    return new Float32Array([f / aspect, 0, 0, 0, 0, f, 0, 0, 0, 0, (far + near) * nf, -1, 0, 0, 2 * far * near * nf, 0]);
  }
  function multiply(a, b) {
    const out = new Float32Array(16);
    for (let c = 0; c < 4; c++) for (let r = 0; r < 4; r++)
      out[c * 4 + r] = a[r] * b[c * 4] + a[4 + r] * b[c * 4 + 1] + a[8 + r] * b[c * 4 + 2] + a[12 + r] * b[c * 4 + 3];
    return out;
  }
  const b = model.bounds || [0, 0, 0, 1, 1, 1];
  const center = [(b[0] + b[3]) / 2, (b[1] + b[4]) / 2, (b[2] + b[5]) / 2];
  const diagonal = Math.hypot(b[3] - b[0], b[4] - b[1], b[5] - b[2]) || 10;
  let camera = { theta: Math.PI / 4, phi: Math.PI / 5, radius: diagonal * 1.65, target: [...center] };
  const minRadius = diagonal * 0.06, maxRadius = diagonal * 30;
  function zoomBy(factor) {
    camera.radius = Math.max(minRadius, Math.min(maxRadius, camera.radius * factor));
    draw();
  }
  function preset(kind) {
    if (kind === "top") { camera.theta = 0; camera.phi = Math.PI / 2 - 0.02; }
    else { camera.theta = Math.PI / 4; camera.phi = Math.PI / 5; }
    camera.target = [...center]; camera.radius = diagonal * 1.65; draw();
  }
  function draw() {
    if (!document.body.contains(canvas)) return;
    const rect = canvas.getBoundingClientRect(), ratio = Math.min(window.devicePixelRatio || 1, 2);
    const w = Math.max(1, Math.round(rect.width * ratio)), h = Math.max(1, Math.round(rect.height * ratio));
    if (canvas.width !== w || canvas.height !== h) { canvas.width = w; canvas.height = h; }
    gl.viewport(0, 0, w, h); gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
    const cp = Math.cos(camera.phi), sp = Math.sin(camera.phi), st = Math.sin(camera.theta), ct = Math.cos(camera.theta);
    const eye = [camera.target[0] + camera.radius * cp * st, camera.target[1] - camera.radius * cp * ct, camera.target[2] + camera.radius * sp];
    // Keep the depth-buffer range close to the visible model. A fixed near/far
    // range spanning ~2,000,000:1 loses precision and makes faces flicker as
    // the user zooms toward the structure.
    const near = Math.max(diagonal * 0.0005, Math.min(diagonal * 0.02, camera.radius - diagonal * 0.75));
    const far = Math.max(near * 100, camera.radius + diagonal * 1.5);
    const proj = perspective(Math.PI / 4, w / h, near, far);
    const mvp = multiply(proj, lookAt(eye, camera.target, [0, 0, 1]));
    gl.useProgram(program); gl.uniformMatrix4fv(uMvp, false, mvp);
    for (const item of buffers) {
      const m = item.mesh;
      if ((floorFilter.value && m.floor !== floorFilter.value) || (typeFilter.value && m.element_type !== typeFilter.value)) continue;
      const hex = colors[m.element_type] || "#b0bec5";
      let rgb = [1, 3, 5].map((i, n) => parseInt(hex.slice(i, i + 2), 16) / 255);
      if (m.model_status === "inferred") rgb = rgb.map(v => v * 0.88 + 0.12);
      if (selected?.uid === m.uid) rgb = rgb.map(v => Math.min(1, v * 1.4 + 0.12));
      gl.uniform3fv(uColor, rgb); gl.bindBuffer(gl.ARRAY_BUFFER, item.buffer);
      gl.enableVertexAttribArray(aPos); gl.vertexAttribPointer(aPos, 3, gl.FLOAT, false, 24, 0);
      gl.enableVertexAttribArray(aNormal); gl.vertexAttribPointer(aNormal, 3, gl.FLOAT, false, 24, 12);
      gl.drawArrays(gl.TRIANGLES, 0, item.count);
    }
  }
  function filteredDraw() { renderList(); draw(); }
  floorFilter.onchange = filteredDraw; typeFilter.onchange = filteredDraw;
  list.addEventListener("click", ev => { const row = ev.target.closest("[data-m3-index]"); if (row) draw(); });
  main.querySelector("#m3Fit").onclick = () => preset("iso");
  main.querySelector("#m3ZoomIn").onclick = () => zoomBy(0.82);
  main.querySelector("#m3ZoomOut").onclick = () => zoomBy(1 / 0.82);
  main.querySelector("#m3Top").onclick = () => preset("top");
  main.querySelector("#m3Iso").onclick = () => preset("iso");
  let drag = null;
  canvas.addEventListener("contextmenu", ev => ev.preventDefault());
  canvas.addEventListener("pointerdown", ev => {
    if (ev.button !== 0 && ev.button !== 2) return;
    canvas.setPointerCapture(ev.pointerId);
    drag = { x: ev.clientX, y: ev.clientY, startX: ev.clientX, startY: ev.clientY, pan: ev.button === 2 || ev.shiftKey, moved: false };
  });
  const endDrag = ev => {
    if (drag) drag = null;
    if (canvas.hasPointerCapture(ev.pointerId)) canvas.releasePointerCapture(ev.pointerId);
  };
  canvas.addEventListener("pointerup", endDrag);
  canvas.addEventListener("pointercancel", endDrag);
  canvas.addEventListener("pointermove", ev => {
    if (!drag) return;
    if (!drag.moved) {
      if (Math.hypot(ev.clientX - drag.startX, ev.clientY - drag.startY) < 4) return;
      drag.moved = true;
      drag.x = ev.clientX;
      drag.y = ev.clientY;
      return;
    }
    const dx = ev.clientX - drag.x, dy = ev.clientY - drag.y; drag.x = ev.clientX; drag.y = ev.clientY;
    if (drag.pan) {
      const scale = camera.radius / Math.max(100, canvas.clientHeight);
      camera.target[0] -= dx * scale * Math.cos(camera.theta); camera.target[1] -= dx * scale * Math.sin(camera.theta); camera.target[2] += dy * scale;
    } else {
      camera.theta -= dx * 0.008; camera.phi = Math.max(0.04, Math.min(Math.PI - 0.04, camera.phi + dy * 0.008));
    }
    draw();
  });
  canvas.addEventListener("wheel", ev => {
    ev.preventDefault();
    const unit = ev.deltaMode === 1 ? 16 : ev.deltaMode === 2 ? canvas.clientHeight : 1;
    const delta = Math.max(-120, Math.min(120, ev.deltaY * unit));
    zoomBy(Math.exp(delta * 0.0009));
  }, { passive: false });
  window.onresize = () => draw();
  draw();
};
